SELECT CASE WHEN cost >= 90 THEN 'high' WHEN cost >= 46 THEN 'mid' ELSE 'low' END cost_bucket, SUM(cost) total_cost, ROUND(SUM(cost) * 100.0 / SUM(SUM(cost)) OVER (), 2) AS pct_of_total FROM shipments GROUP BY CASE WHEN cost >= 90 THEN 'high' WHEN cost >= 46 THEN 'mid' ELSE 'low' END ORDER BY pct_of_total, 2 DESC
